cssCode:
.cylinder-wrap {
  width: 100%; height: 100vh; perspective: 1000px;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.cylinder {
  position: relative; width: 300px; height: 50px;
  transform-style: preserve-3d; transition: transform 0.1s linear;
}
.cylinder-panel {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 40px; font-weight: 900; font-family: sans-serif;
  color: transparent; -webkit-text-stroke: 1px #00ffcc;
  backface-visibility: hidden;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#050510;';

// સ્ક્રોલ કરવા માટે મોટી જગ્યા
const scrollDummy = document.createElement('div');
scrollDummy.style.height = '300vh'; 

const stickyWrap = document.createElement('div');
stickyWrap.style.cssText = 'position:sticky; top:0; height:100vh; overflow:hidden; display:flex; align-items:center; justify-content:center; perspective:1000px;';

const cylinder = document.createElement('div');
cylinder.className = 'cylinder';

// સિલિન્ડર (ગોળાકાર) માટે 8 પેનલ્સ
const numPanels = 8;
const radius = Math.round((300 / 2) / Math.tan(Math.PI / numPanels));

for (let i = 0; i < numPanels; i++) {
  const panel = document.createElement('div');
  panel.className = 'cylinder-panel';
  panel.innerText = 'MOTIONZYNC';
  const angle = (360 / numPanels) * i;
  panel.style.transform = `rotateX(${angle}deg) translateZ(${radius}px)`;
  cylinder.appendChild(panel);
}

stickyWrap.appendChild(cylinder);
scrollDummy.appendChild(stickyWrap);
c.appendChild(scrollDummy);

c.addEventListener('scroll', () => {
  const maxScroll = c.scrollHeight - c.clientHeight;
  const progress = c.scrollTop / maxScroll;
  // સ્ક્રોલ કરવાથી આખું સિલિન્ડર 3D માં ગોળ ફરશે
  cylinder.style.transform = `rotateX(${progress * -720}deg)`;
});
